# Flat-point source budget reserves the doctrine and deployed-HQ factors.
# Mirrors cbrn_doctrine_modifier.weather_recon_*; native accumulation still requires validation.
@CBRN_WEATHER_RECON_BASIC = 0.01
@CBRN_WEATHER_RECON_IMPROVED = 0.02
@CBRN_WEATHER_RECON_ADVANCED = 0.03

# Wind Detection Technologies
portable_anemometer = {
	allow = { always = no }
	research_cost = @CBRN_TECH_COST_BASIC
	start_year = 1918
	category_cbrn_reconnaissance = { recon = @CBRN_WEATHER_RECON_BASIC }
	ai_will_do = { factor = 0 }
}

meteorological_stations = {
	allow = { always = no }
	research_cost = @CBRN_TECH_COST_BASIC
	start_year = 1936
	category_cbrn_reconnaissance = { recon = @CBRN_WEATHER_RECON_IMPROVED }
	ai_will_do = { factor = 0 }
}

upper_air_soundings = {
	allow = { always = no }
	research_cost = @CBRN_TECH_COST_BASIC
	start_year = 1940
	category_cbrn_reconnaissance = { recon = @CBRN_WEATHER_RECON_ADVANCED }
	ai_will_do = { factor = 0 }
}

on_research_complete = {
	set_technology = { portable_anemometer = 1 popup = no }
	cbrn_reveal_protection_decision_surface = yes

group = support

categories = {
	category_support_battalions
	category_divisional_support_battalions
	category_cbrn_hq
	category_army
}

deployed_leader_modifiers = {
	planning_speed = @CBRN_HQ_OPERATIONS_PLANNING
	recon_factor = @CBRN_HQ_OPERATIONS_RECON
}

group = support

categories = {
	category_support_battalions
	category_divisional_support_battalions
	category_cbrn_hq
	category_army
}

deployed_leader_modifiers = {
	wounded_chance_factor = @CBRN_HQ_MEDICAL_WOUNDED
	sickness_chance = @CBRN_HQ_MEDICAL_SICKNESS
	recon_factor = @CBRN_HQ_MEDICAL_RECON
}
